23	/**
24	 * A short, looping window of the real fight video around one labelled
25	 * event's frame, with the real FighterOverlay boxes/skeletons drawn on top —
26	 * reuses the same frame-numbering contract and requestVideoFrameCallback
27	 * draw loop as Player.tsx, just scoped to a strict 0.6s window instead of
28	 * the whole fight.
29	 */
30	export default function ClipPlayer({ fight, frame, corner }: ClipPlayerProps) {
31	  const videoRef = useRef<HTMLVideoElement>(null);
32	  const overlayRef = useRef<FighterOverlayHandle>(null);
33	  const rafRef = useRef<number | null>(null);
34	  const [isPlaying, setIsPlaying] = useState(true);
35	  const [showBoxes, setShowBoxes] = useState(true);
36	  const [showSkeletons, setShowSkeletons] = useState(true);
37	  const [speed, setSpeed] = useState<Speed>(loadSpeed);
38	  const [currentTime, setCurrentTime] = useState(0);
39	
40	  useEffect(() => { localStorage.setItem(SPEED_KEY, String(speed)); }, [speed]);
41	
42	  const { frameMap } = useFighterFrames(fight.id);
43	  const { events: swapEvents } = useEvents(fight.id, { source: 'label', kind: 'corner_swap' });
44	  const cornerSwapSpans = swapEvents.map((e) => ({ frame: e.frame, end_frame: e.end_frame }));
45	
46	  const fps = fight.fps;
47	  // Whole-frame math so the clip is a strict CLIP_DURATION_SECS regardless of
48	  // fps rounding — a time-based half-window would drift by fractional frames.
49	  const windowFrames = Math.max(1, Math.round(CLIP_DURATION_SECS * fps));
50	  const eventFrameIdx = frame - 1; // 0-based
51	  const windowStartFrame = Math.max(0, eventFrameIdx - Math.floor(windowFrames / 2));
52	  const windowEndFrame = windowStartFrame + windowFrames;
53	  const windowStart = windowStartFrame / fps;
54	  const windowEnd = windowEndFrame / fps;
55	
56	  // Jump to the event's window whenever the reviewed event changes.
57	  useEffect(() => {
58	    const video = videoRef.current;
59	    if (!video) return;
60	    const seek = () => {
61	      video.currentTime = windowStart;
62	      video.playbackRate = speed;
63	      setCurrentTime(windowStart);
64	      video.play().catch(() => {});
65	      setIsPlaying(true);
66	    };
67	    if (video.readyState >= 1) seek();
68	    else video.addEventListener('loadedmetadata', seek, { once: true });
69	    return () => video.removeEventListener('loadedmetadata', seek);
70	    // eslint-disable-next-line react-hooks/exhaustive-deps
71	  }, [fight.id, frame]);
72	
73	  useEffect(() => {
74	    const video = videoRef.current;
75	    if (video) video.playbackRate = speed;
76	  }, [speed]);
77	
78	  // Loop playback within [windowStart, windowEnd] and draw the overlay per frame.
79	  useEffect(() => {
80	    const video = videoRef.current;
81	    if (!video || !isPlaying) {
82	      if (rafRef.current !== null && video) {
83	        video.cancelVideoFrameCallback(rafRef.current);
84	        rafRef.current = null;
85	      }
86	      return;
87	    }
88	    const tick = (_now: DOMHighResTimeStamp, metadata: VideoFrameCallbackMetadata) => {
89	      let t = metadata.mediaTime;
90	      if (t >= windowEnd) {
91	        video.currentTime = windowStart;
92	        t = windowStart;
93	      }
94	      overlayRef.current?.draw(Math.floor(t * fps) + 1);
95	      setCurrentTime(t);
96	      rafRef.current = video.requestVideoFrameCallback(tick);
97	    };
98	    rafRef.current = video.requestVideoFrameCallback(tick);
99	    return () => {
100	      if (rafRef.current !== null) video.cancelVideoFrameCallback(rafRef.current);
101	      rafRef.current = null;
102	    };
103	  }, [isPlaying, windowStart, windowEnd, fps]);
104	
105	  const togglePlay = useCallback(() => {
106	    const video = videoRef.current;
107	    if (!video) return;
108	    if (isPlaying) { video.pause(); setIsPlaying(false); } else { video.play().catch(() => {}); setIsPlaying(true); }
109	  }, [isPlaying]);
110	
111	  const handleScrub = (t: number) => {
112	    const video = videoRef.current;
113	    if (!video) return;
114	    video.pause();
115	    setIsPlaying(false);
116	    video.currentTime = t;
117	    setCurrentTime(t);
118	    overlayRef.current?.draw(Math.floor(t * fps) + 1);
119	  };
120	
121	  const stepFrame = useCallback((delta: number) => {
122	    const video = videoRef.current;
123	    if (!video) return;
124	    video.pause();
125	    setIsPlaying(false);
126	    const t = Math.min(Math.max(video.currentTime + delta / fps, windowStart), windowEnd);
127	    video.currentTime = t;
128	    setCurrentTime(t);
129	    overlayRef.current?.draw(Math.floor(t * fps) + 1);
130	  }, [fps, windowStart, windowEnd]);
131	
132	  const clipFrame = Math.floor((currentTime - windowStart) * fps) + 1;
133	  const clipFrames = Math.max(1, Math.round((windowEnd - windowStart) * fps));
134	
135	  return (
136	    <div>
137	      <div style={{ display: 'flex', alignItems: 'center', gap: 9, flexWrap: 'wrap', marginBottom: 10 }}>
138	        <button type="button" className={'pill' + (showSkeletons ? ' active' : '')} onClick={() => setShowSkeletons((v) => !v)} style={{ padding: '4px 10px', fontSize: 11 }}>Skeleton</button>
139	        <button type="button" className={'pill' + (showBoxes ? ' active' : '')} onClick={() => setShowBoxes((v) => !v)} style={{ padding: '4px 10px', fontSize: 11 }}>Box</button>
140	      </div>
141	
142	      <div style={{ position: 'relative', width: '100%', maxWidth: 720, margin: '0 auto', borderRadius: 12, overflow: 'hidden', border: '1px solid rgba(255,255,255,0.07)', background: '#000' }}>
143	        <video
144	          ref={videoRef}
145	          src={`/fights/${fight.id}/video`}
146	          muted
147	          playsInline
148	          style={{ width: '100%', display: 'block' }}
149	          onPlay={() => setIsPlaying(true)}
150	          onPause={() => setIsPlaying(false)}
151	        />
152	        <FighterOverlay
153	          ref={overlayRef}
154	          frameMap={frameMap}
155	          fightWidth={fight.width}
156	          fightHeight={fight.height}
157	          showBoxes={showBoxes}
158	          showSkeletons={showSkeletons}
159	          highlightCorner={corner as 0 | 1 | null}
160	          dimUnhighlighted
161	          cornerSwapSpans={cornerSwapSpans}
162	        />
163	      </div>
164	
165	      <div style={{ display: 'flex', alignItems: 'center', gap: 11, flexWrap: 'wrap', marginTop: 11 }}>
166	        <button type="button" onClick={() => stepFrame(-1)} title="Previous frame" style={{ width: 28, height: 28, borderRadius: 8, display: 'grid', placeItems: 'center', background: 'rgba(255,255,255,0.05)', border: '1px solid var(--border-glass)', color: 'var(--text-secondary)', cursor: 'pointer', flexShrink: 0 }}>
167	          <span className="material-symbols-outlined" style={{ fontSize: 15 }}>skip_previous</span>
168	        </button>
169	        <button type="button" className="lab-ibtn" onClick={togglePlay} title="Play / pause" style={{ width: 32, height: 32, borderRadius: 8, display: 'grid', placeItems: 'center', background: 'rgba(255,255,255,0.05)', border: '1px solid var(--border-glass)', color: 'var(--text-secondary)', cursor: 'pointer', flexShrink: 0 }}>
170	          <span className="material-symbols-outlined" style={{ fontSize: 16 }}>{isPlaying ? 'pause' : 'play_arrow'}</span>
171	        </button>
172	        <button type="button" onClick={() => stepFrame(1)} title="Next frame" style={{ width: 28, height: 28, borderRadius: 8, display: 'grid', placeItems: 'center', background: 'rgba(255,255,255,0.05)', border: '1px solid var(--border-glass)', color: 'var(--text-secondary)', cursor: 'pointer', flexShrink: 0 }}>
173	          <span className="material-symbols-outlined" style={{ fontSize: 15 }}>skip_next</span>
174	        </button>
175	        <input
176	          type="range"
177	          min={windowStart}
178	          max={windowEnd}
179	          step={1 / fps}
180	          value={currentTime}
181	          onChange={(e) => handleScrub(Number(e.target.value))}
182	          style={{ flex: 1, minWidth: 140, accentColor: 'var(--cyan-400)', height: 4 }}
183	          aria-label="Frame"
184	        />
185	        <span style={{ fontFamily: 'ui-monospace,Menlo,monospace', fontSize: 11, fontWeight: 700, color: 'var(--text-muted)' }}>
186	          {String(Math.min(clipFrame, clipFrames)).padStart(2, '0')} / {clipFrames}
187	        </span>
188	        <div style={{ display: 'flex', gap: 4, padding: 3, borderRadius: 9, background: 'rgba(0,0,0,0.28)', border: '1px solid var(--border-subtle)' }}>
189	          {SPEEDS.map((s) => (
190	            <button key={s} type="button" className={'pill' + (speed === s ? ' active' : '')} onClick={() => setSpeed(s)} title="Playback speed — remembered next time" style={{ padding: '4px 9px', fontSize: 11 }}>{s}×</button>
191	          ))}
192	        </div>
193	      </div>
194	      <div style={{ marginTop: 9, fontSize: 10.5, fontWeight: 600, color: 'var(--text-disabled)' }}>
195	        {fight.video_path.split('/').pop()} · {fps} fps
196	      </div>
197	    </div>
198	  );
199	}
